// Similar to ToIdentifierVector(), but returns a vector of IdString's,
// avoiding the need to make copies.
func (h *ASTPathExpression) ToIdStringVector() ([]*IdString, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(338, 0, buf)
	if err != nil {
		return nil, err
	}
	var items []*IdString
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f == 1 {
			sub := pr.readSubmessage()
			p := readHandlePtr(sub.data)
			if p != 0 {
				child := newIdStringNoFinalizer(p)
				child.setKeepAlive(h)
				items = append(items, child)
			}
		} else {
			pr.skip(w)
		}
	}
	return items, nil
}

// Return this PathExpression as a dotted SQL identifier string, with
// quoting if necessary.  If
// <max
// _prefix_size> is non-zero, include at most
// that many identifiers from the prefix of
// <path
// >.
func (h *ASTPathExpression) ToIdentifierPathString(maxPrefixSize uint64) (string, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	buf = pbAppendUint64(buf, 2, maxPrefixSize)
	resp, err := invokeMethod(338, 1, buf)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

// Return the vector of identifier strings (without quoting).
func (h *ASTPathExpression) ToIdentifierVector() ([]string, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(338, 2, buf)
	if err != nil {
		return nil, err
	}
	var items []string
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f != 1 {
			pr.skip(w)
			continue
		}
		items = append(items, pr.readString())
	}
	return items, nil
}

