// The optional alias for the result of the recursive union. Note
// it acts as both the input table to the next iteration, and the
// output table of the recursive union. For example, in the
// following query:
//
// ```SQL
// FROM TreeNodes
// |> RECURSIVE UNION ALL (
//
//	|> JOIN TreeNodes AS child_node ON
//	    nodes.id = child_node.parent_id
//	|> SELECT child_node.*
//
// ) AS nodes;
// ```
//
// The alias `nodes` is the output table of the recursive union,
// and the input table to the next iteration.
func (h *ASTPipeRecursiveUnion) Alias() (*ASTAlias, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(362, 0, buf)
	if err != nil {
		return nil, err
	}
	return decodeChildHandle(resp, 1, h, newASTAliasNoFinalizer), nil
}

// The input subpipeline for the recursive union operator. The
// input table to the subpipeline is the output of the previous
// iteration.
//
// Example:
//
// ```SQL
// FROM KeyValue
// |> RECURSIVE UNION ALL (
//
//	|> SET value = value + 1
//	|> WHERE key
//
// <
// 10
//
//	)
func (h *ASTPipeRecursiveUnion) InputSubpipeline() (*ASTSubpipeline, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(362, 1, buf)
	if err != nil {
		return nil, err
	}
	return decodeChildHandle(resp, 1, h, newASTSubpipelineNoFinalizer), nil
}

// The input subquery for the recursive union operator.
//
// Example:
//
// ```SQL
// FROM KeyValue
// |> RECURSIVE UNION ALL (
//
//	SELECT key, value + 1 AS value
//	FROM KeyValue
//	WHERE key
//
// <
// 10
//
//	)
