// Returns non-built-in rewriters that will be applied after all built-in
// rewriters.
func (h *AnalyzerOptions) TrailingRewriters() ([]RewriterNode, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(540, 84, buf)
	if err != nil {
		return nil, err
	}
	var items []RewriterNode
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f == 1 {
			sub := pr.readSubmessage()
			p := readHandlePtr(sub.data)
			if p != 0 {
				resolved, _ := resolveAbstractHandle(p)
				if v, ok := resolved.(RewriterNode); ok {
					if ka, okKA := v.(interface{ setKeepAlive(any) }); okKA {
						ka.setKeepAlive(h)
					}
					items = append(items, v)
				}
			}
		} else {
			pr.skip(w)
		}
	}
	return items, nil
}

