// Returns undeclared positional parameters found the query and their inferred
// types. The index in the vector corresponds with the position of the
// undeclared parameter--for example, the first element in the vector is the
// type of the undeclared parameter at position 1 and so on.
func (h *AnalyzerOutput) UndeclaredPositionalParameters() ([]Googlesql_TypeNode, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(542, 10, buf)
	if err != nil {
		return nil, err
	}
	var items []Googlesql_TypeNode
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f == 1 {
			sub := pr.readSubmessage()
			p := readHandlePtr(sub.data)
			if p != 0 {
				resolved, _ := resolveAbstractHandle(p)
				if v, ok := resolved.(Googlesql_TypeNode); ok {
					if ka, okKA := v.(interface{ setKeepAlive(any) }); okKA {
						ka.setKeepAlive(h)
					}
					items = append(items, v)
				}
			}
		} else {
			pr.skip(w)
		}
	}
	return items, nil
}

