// The Function interface identifies the functions available in a
// query engine.  Each Function includes a set of FunctionSignatures, where
// a signature indicates:
//
//  1. Argument and result types.
//  2. A 'context' for the signature.
//
// A Function also indicates the 'group' it belongs to.
//
// The Function also includes
// <function
// _options_> for specifying additional
// resolution requirements, if any.  Additionally,
// <function
// _options_> can
// identify a function alias/synonym that Catalogs must expose for function
// lookups by name.
type Function struct {
	ptr       uint64
	keepAlive []any
}

func (h *Function) rawPtr() uint64 { return h.ptr }

func (h *Function) setKeepAlive(v any) {
	if h != nil && v != nil {
		h.keepAlive = append(h.keepAlive, v)
	}
}

func (h *Function) clearPtr() {
	if h != nil {
		h.ptr = 0
	}
}

func newFunction(ptr uint64) *Function {
	h := &Function{ptr: ptr}
	runtime.SetFinalizer(h, (*Function).free)
	return h
}

func newFunctionNoFinalizer(ptr uint64) *Function {
	h := &Function{ptr: ptr}
	return h
}

func NewFunction(namePath []string, group string, mode FunctionEnums_Mode, functionSignatures []*FunctionSignature, functionOptions *FunctionOptions) (*Function, error) {
	var buf []byte
	for _, item := range namePath {
		buf = pbAppendString(buf, 1, item)
	}
	buf = pbAppendString(buf, 2, group)
	buf = pbAppendInt32(buf, 3, int32(mode))
	for _, item := range functionSignatures {
		if item != nil {
			buf = pbAppendHandle(buf, 4, item.rawPtr())
		}
	}
	if functionOptions != nil {
		buf = pbAppendSubmessage(buf, 5, functionOptions.marshal())
	}
	resp, err := invokeMethod(604, 0, buf)
	if err != nil {
		return nil, err
	}
	return newFunction(readScalarAtField(resp, 1, (*pbReader).readUint64)), nil
}

