// Returns all of the function signatures.
func (h *Function) Signatures() ([]*FunctionSignature, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(604, 52, buf)
	if err != nil {
		return nil, err
	}
	var items []*FunctionSignature
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f == 1 {
			sub := pr.readSubmessage()
			p := readHandlePtr(sub.data)
			if p != 0 {
				child := newFunctionSignatureNoFinalizer(p)
				child.setKeepAlive(h)
				items = append(items, child)
			}
		} else {
			pr.skip(w)
		}
	}
	return items, nil
}

