// Returns the component types of this composite type, in a
// deterministic order. The type must always return its component types in
// the same order.
// Otherwise, returns an empty vector.
//
// This function is used to create `AnnotationMap`s with the correct
// structure.
//
// ARRAY and RANGE:           have exactly one component type.
// MAP and GRAPH_PATH:        have 2 component types.
// STRUCT and GRAPH_ELEMENT:  have N component types.
// Non-composite, e.g. INT64: have no component types (return an empty list).
func (h *Googlesql_Type) ComponentTypes() ([]Googlesql_TypeNode, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(1348, 13, buf)
	if err != nil {
		return nil, err
	}
	var items []Googlesql_TypeNode
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f == 1 {
			sub := pr.readSubmessage()
			p := readHandlePtr(sub.data)
			if p != 0 {
				resolved, _ := resolveAbstractHandle(p)
				if v, ok := resolved.(Googlesql_TypeNode); ok {
					if ka, okKA := v.(interface{ setKeepAlive(any) }); okKA {
						ka.setKeepAlive(h)
					}
					items = append(items, v)
				}
			}
		} else {
			pr.skip(w)
		}
	}
	return items, nil
}

