// If the JSON value being referenced is an array, returns the element at
// 'index'. If such element does not exist (index >= GetArraySize()), then
// the returned value is an invalid object.
//
// Requires IsArray() to be true. Otherwise, the call results in ABSL_LOG(FATAL).
func (h *JSONValueConstRef) GetArrayElement(index uint64) (*JSONValueConstRef, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	buf = pbAppendUint64(buf, 2, index)
	resp, err := invokeMethod(634, 1, buf)
	if err != nil {
		return nil, err
	}
	return decodeChildHandle(resp, 1, h, newJSONValueConstRefNoFinalizer), nil
}

// If the JSON value being referenced is an array, returns all the elements.
//
// Requires IsArray() to be true. Otherwise, the call results in ABSL_LOG(FATAL).
func (h *JSONValueConstRef) GetArrayElements() ([]*JSONValueConstRef, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(634, 2, buf)
	if err != nil {
		return nil, err
	}
	var items []*JSONValueConstRef
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f == 1 {
			sub := pr.readSubmessage()
			p := readHandlePtr(sub.data)
			if p != 0 {
				child := newJSONValueConstRefNoFinalizer(p)
				child.setKeepAlive(h)
				items = append(items, child)
			}
		} else {
			pr.skip(w)
		}
	}
	return items, nil
}

