// message) for procedure signature. For example:
// "PROCEDURE_NAME(DATE, DATE, DATE_TIME_PART)"
func (h *Procedure) GetSupportedSignatureUserFacingText(productMode ProductMode) (string, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	buf = pbAppendInt32(buf, 2, int32(productMode))
	resp, err := invokeMethod(657, 2, buf)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

