// For join ROWs or MULTIROWs (where IsJoin is true), these are present and
// indicate the columns used to load joined rows.
// The `bound_source_columns` on `bound_source_table` join to
// `bound_columns on `table`.
// For non-join ROWs (representing table scans), these are unset.
func (h *RowType) BoundColumns() ([]Googlesql_ColumnNode, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(1288, 18, buf)
	if err != nil {
		return nil, err
	}
	var items []Googlesql_ColumnNode
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f == 1 {
			sub := pr.readSubmessage()
			p := readHandlePtr(sub.data)
			if p != 0 {
				resolved, _ := resolveAbstractHandle(p)
				if v, ok := resolved.(Googlesql_ColumnNode); ok {
					if ka, okKA := v.(interface{ setKeepAlive(any) }); okKA {
						ka.setKeepAlive(h)
					}
					items = append(items, v)
				}
			}
		} else {
			pr.skip(w)
		}
	}
	return items, nil
}

