func (h *SimpleCatalog) CatalogNames() ([]string, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(1293, 85, buf)
	if err != nil {
		return nil, err
	}
	var items []string
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f != 1 {
			pr.skip(w)
			continue
		}
		items = append(items, pr.readString())
	}
	return items, nil
}

func (h *SimpleCatalog) Catalogs() ([]CatalogNode, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(1293, 86, buf)
	if err != nil {
		return nil, err
	}
	var items []CatalogNode
	pr := &pbReader{data: resp}
	for f, w, ok := pr.next(); ok; f, w, ok = pr.next() {
		if f == 1 {
			sub := pr.readSubmessage()
			p := readHandlePtr(sub.data)
			if p != 0 {
				resolved, _ := resolveAbstractHandle(p)
				if v, ok := resolved.(CatalogNode); ok {
					if ka, okKA := v.(interface{ setKeepAlive(any) }); okKA {
						ka.setKeepAlive(h)
					}
					items = append(items, v)
				}
			}
		} else {
			pr.skip(w)
		}
	}
	return items, nil
}

