// Constructs a new TVF object with the given name, group and argument
// signatures.
//
// Each TVF may accept value or relation arguments. The signature specifies
// whether each argument should be a value or a relation. For a value
// argument, the signature may specify a concrete Type or a (possibly
// templated) SignatureArgumentKind. For relation arguments, the signature
// should use ARG_TYPE_RELATION, and any relation will be accepted as an
// argument.
func NewTableValuedFunction(functionNamePath []string, group string, signatures []*FunctionSignature, tvfOptions *TableValuedFunctionOptions) (*TableValuedFunction, error) {
	var buf []byte
	for _, item := range functionNamePath {
		buf = pbAppendString(buf, 1, item)
	}
	buf = pbAppendString(buf, 2, group)
	for _, item := range signatures {
		if item != nil {
			buf = pbAppendHandle(buf, 3, item.rawPtr())
		}
	}
	if tvfOptions != nil {
		buf = pbAppendSubmessage(buf, 4, tvfOptions.marshal())
	}
	resp, err := invokeMethod(1342, 0, buf)
	if err != nil {
		return nil, err
	}
	return newTableValuedFunction(readScalarAtField(resp, 1, (*pbReader).readUint64)), nil
}

