// Rewriter that expands function signatures for variadic functions like
// MAP_INSERT, MAP_INSERT_OR_REPLACE, MAP_REPLACE, and MAP_DELETE to prepare
// them for inlining via REWRITE_BUILTIN_FUNCTION_INLINER.
type VariadicFunctionSignatureExpander struct {
	*Rewriter
}

func newVariadicFunctionSignatureExpander(ptr uint64) *VariadicFunctionSignatureExpander {
	h := &VariadicFunctionSignatureExpander{
		Rewriter: newRewriterNoFinalizer(ptr),
	}
	runtime.SetFinalizer(h, (*VariadicFunctionSignatureExpander).free)
	return h
}

func newVariadicFunctionSignatureExpanderNoFinalizer(ptr uint64) *VariadicFunctionSignatureExpander {
	h := &VariadicFunctionSignatureExpander{
		Rewriter: newRewriterNoFinalizer(ptr),
	}
	return h
}

func (h *VariadicFunctionSignatureExpander) Name() (string, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	resp, err := invokeMethod(1362, 0, buf)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

func (h *VariadicFunctionSignatureExpander) Rewrite(options *AnalyzerOptions, input ResolvedNode, catalog CatalogNode, typeFactory *TypeFactory, analyzerOutputProperties *AnalyzerOutputProperties) (ResolvedNode, error) {
	buf := pbAppendHandle(nil, 1, h.ptr)
	if options != nil {
		buf = pbAppendHandle(buf, 2, options.rawPtr())
	}
	if input != nil {
		buf = pbAppendHandle(buf, 3, input.rawPtr())
	}
	if catalog != nil {
		buf = pbAppendHandle(buf, 4, catalog.rawPtr())
	}
	if typeFactory != nil {
		buf = pbAppendHandle(buf, 5, typeFactory.rawPtr())
	}
	if analyzerOutputProperties != nil {
		buf = pbAppendHandle(buf, 6, analyzerOutputProperties.rawPtr())
	}
	resp, err := invokeMethod(1362, 1, buf)
	if input != nil {
		if _c, _ok := input.(interface{ clearPtr() }); _ok {
			_c.clearPtr()
		}
	}
	if err != nil {
		return nil, err
	}
	return decodeAbstractAs[ResolvedNode](resp, 1, h, "ResolvedNode")
}

func (h *VariadicFunctionSignatureExpander) free() {
	if h.ptr != 0 {
		buf := pbAppendHandle(nil, 1, h.ptr)
		module().invoke(1362, 2, buf)
		h.ptr = 0
	}
}

// A "sink" or collector object for SQL warnings. This class also provides
// de-duplication of warnings so that the same warning only occurs once per
// sql statement.
type WarningSink struct {
	ptr       uint64
	keepAlive []any
}

func (h *WarningSink) rawPtr() uint64 { return h.ptr }

func (h *WarningSink) setKeepAlive(v any) {
	if h != nil && v != nil {
		h.keepAlive = append(h.keepAlive, v)
	}
}

func (h *WarningSink) clearPtr() {
	if h != nil {
		h.ptr = 0
	}
}

func newWarningSink(ptr uint64) *WarningSink {
	h := &WarningSink{ptr: ptr}
	runtime.SetFinalizer(h, (*WarningSink).free)
	return h
}

func newWarningSinkNoFinalizer(ptr uint64) *WarningSink {
	h := &WarningSink{ptr: ptr}
	return h
}

// `consider_location` controls whether the warning location is considered
// when deduplicating. When true, two warnings with the same code and message
// but different locations will be considered different warnings and not
// de-duplicated. This is useful when warnings will be displayed in a
// graphical user interface or when warnings have fix suggestions attached.
func NewWarningSink(considerLocation bool) (*WarningSink, error) {
	var buf []byte
	buf = pbAppendBool(buf, 1, considerLocation)
	resp, err := invokeMethod(1363, 0, buf)
	if err != nil {
		return nil, err
	}
	return newWarningSink(readScalarAtField(resp, 1, (*pbReader).readUint64)), nil
}

// Clear the sink so that `warnings()` is empty and the next warning added
// is guaranteed not to be a duplicate.
func (h *WarningSink) Reset() error {
	buf := pbAppendHandle(nil, 1, h.ptr)
	_, err := invokeMethod(1363, 1, buf)
	return err
}

// Access the unique warnings added so far in no particular order.
func (h *WarningSink) Warnings() error {
	buf := pbAppendHandle(nil, 1, h.ptr)
	_, err := invokeMethod(1363, 2, buf)
	return err
}

func (h *WarningSink) free() {
	if h.ptr != 0 {
		buf := pbAppendHandle(nil, 1, h.ptr)
		module().invoke(1363, 3, buf)
		h.ptr = 0
	}
}

