// Analyze a GoogleSQL expression.  The expression may include query
// parameters, subqueries, and any other valid expression syntax.
//
// The Catalog provides functions and named data types as usual.  If it
// includes Tables, those tables will be queryable in subqueries inside the
// expression.
//
// Column names added to
// <options
// > with AddExpressionColumn will be usable
// in the expression, and will show up as ResolvedExpressionColumn nodes in
// the resolved output.
//
// Can return errors that point at a location in the input. This location can be
// reported in multiple ways depending on
// <options
// .error_message_mode()>.
func AnalyzeExpression(sql string, options *AnalyzerOptions, catalog CatalogNode, typeFactory *TypeFactory) (*AnalyzerOutput, error) {
	var buf []byte
	buf = pbAppendString(buf, 1, sql)
	if options != nil {
		buf = pbAppendHandle(buf, 2, options.rawPtr())
	}
	if catalog != nil {
		buf = pbAppendHandle(buf, 3, catalog.rawPtr())
	}
	if typeFactory != nil {
		buf = pbAppendHandle(buf, 4, typeFactory.rawPtr())
	}
	resp, err := invokeMethod(0, 0, buf)
	if err != nil {
		return nil, err
	}
	ptr := readPtrAtField(resp, 2)
	if ptr == 0 {
		return nil, nil
	}
	child := newAnalyzerOutput(ptr)
	child.setKeepAlive(options)
	child.setKeepAlive(catalog)
	child.setKeepAlive(typeFactory)
	return child, nil
}

// Analyze one statement from a string that may contain multiple statements.
// This can be called in a loop with the same
// <resume
// _location> to parse
// all statements from a string.
//
// On successful return,
//
// <
// *at_end_of_input> is true if parsing reached the end of the string.
//
// <
// *output> contains the next statement found.
//
// Statements are separated by semicolons.  A final semicolon is not required
// on the last statement.  If only whitespace and comments follow the
// semicolon,
// <
// *at_end_of_input> will be set.
//
// This can return errors that point at a location in the input. How this
// location is reported is given by
// <options
// .error_message_mode()>.
//
// After an error,
// <resume
// _location> may not be updated and analyzing further
// statements is not supported.
func AnalyzeNextStatement(resumeLocation *ParseResumeLocation, optionsIn *AnalyzerOptions, catalog CatalogNode, typeFactory *TypeFactory) (*AnalyzerOutput, error) {
	var buf []byte
	if resumeLocation != nil {
		buf = pbAppendHandle(buf, 1, resumeLocation.rawPtr())
	}
	if optionsIn != nil {
		buf = pbAppendHandle(buf, 2, optionsIn.rawPtr())
	}
	if catalog != nil {
		buf = pbAppendHandle(buf, 3, catalog.rawPtr())
	}
	if typeFactory != nil {
		buf = pbAppendHandle(buf, 4, typeFactory.rawPtr())
	}
	resp, err := invokeMethod(0, 1, buf)
	if err != nil {
		return nil, err
	}
	ptr := readPtrAtField(resp, 2)
	if ptr == 0 {
		return nil, nil
	}
	child := newAnalyzerOutput(ptr)
	child.setKeepAlive(resumeLocation)
	child.setKeepAlive(optionsIn)
	child.setKeepAlive(catalog)
	child.setKeepAlive(typeFactory)
	return child, nil
}

