// <
// *at_end_of_input> will be true if parsing reached
// the end of the string.
//
// Statements are separated by semicolons.  A final semicolon is not required
// on the last statement.  If only whitespace and comments follow the
// semicolon,
// <
// *at_end_of_input> will be set to true.  Otherwise, it will be set
// to false.  Script statements are not supported.
//
// After a parse error,
// <resume
// _location> is not updated and parsing further
// statements is not supported.
//
// This can return errors annotated with an ErrorLocation payload that indicates
// the input location of an error.
func ParseNextStatement(resumeLocation *ParseResumeLocation, parserOptionsIn *ParserOptions) (*ParserOutput, error) {
	var buf []byte
	if resumeLocation != nil {
		buf = pbAppendHandle(buf, 1, resumeLocation.rawPtr())
	}
	if parserOptionsIn != nil {
		buf = pbAppendHandle(buf, 2, parserOptionsIn.rawPtr())
	}
	resp, err := invokeMethod(0, 8, buf)
	if err != nil {
		return nil, err
	}
	ptr := readPtrAtField(resp, 2)
	if ptr == 0 {
		return nil, nil
	}
	child := newParserOutput(ptr)
	child.setKeepAlive(resumeLocation)
	child.setKeepAlive(parserOptionsIn)
	return child, nil
}

// Parses
// <script
// _string> and returns the parser output in
// <output
// > upon
// success.
//
// A terminating semicolon is optional for the last statement in the script,
// and mandatory for all other statements.
func ParseScript(scriptString string, parserOptionsIn *ParserOptions, errorMessageOptions *ErrorMessageOptions) (*ParserOutput, error) {
	var buf []byte
	buf = pbAppendString(buf, 1, scriptString)
	if parserOptionsIn != nil {
		buf = pbAppendHandle(buf, 2, parserOptionsIn.rawPtr())
	}
	if errorMessageOptions != nil {
		buf = pbAppendSubmessage(buf, 3, errorMessageOptions.marshal())
	}
	resp, err := invokeMethod(0, 9, buf)
	if err != nil {
		return nil, err
	}
	ptr := readPtrAtField(resp, 2)
	if ptr == 0 {
		return nil, nil
	}
	child := newParserOutput(ptr)
	child.setKeepAlive(parserOptionsIn)
	return child, nil
}

// Parses
// <statement
// _string> and returns the parser output in
// <output
// > upon
// success. The AST can be retrieved from output->statement().
//
// A semi-colon following the statement is optional.
//
// Script statements are not supported.
//
// This can return errors annotated with an ErrorLocation payload that indicates
// the input location of an error.
func ParseStatement(statementString string, parserOptionsIn *ParserOptions) (*ParserOutput, error) {
	var buf []byte
	buf = pbAppendString(buf, 1, statementString)
	if parserOptionsIn != nil {
		buf = pbAppendHandle(buf, 2, parserOptionsIn.rawPtr())
	}
	resp, err := invokeMethod(0, 10, buf)
	if err != nil {
		return nil, err
	}
	ptr := readPtrAtField(resp, 2)
	if ptr == 0 {
		return nil, nil
	}
	child := newParserOutput(ptr)
	child.setKeepAlive(parserOptionsIn)
	return child, nil
}

// Parses
// <type
// _string> as a type name and returns the parser output in
// <output
// >
// upon success. The AST can be retrieved from output->type().
//
// This can return errors annotated with an ErrorLocation payload that indicates
// the input location of an error.
func ParseType(typeString string, parserOptionsIn *ParserOptions) (*ParserOutput, error) {
	var buf []byte
	buf = pbAppendString(buf, 1, typeString)
	if parserOptionsIn != nil {
		buf = pbAppendHandle(buf, 2, parserOptionsIn.rawPtr())
	}
	resp, err := invokeMethod(0, 11, buf)
	if err != nil {
		return nil, err
	}
	ptr := readPtrAtField(resp, 2)
	if ptr == 0 {
		return nil, nil
	}
	child := newParserOutput(ptr)
	child.setKeepAlive(parserOptionsIn)
	return child, nil
}

// Unparse a given AST back to a canonical SQL string and return it.
// Works for any AST node.
func Unparse(root ASTNode) (string, error) {
	var buf []byte
	if root != nil {
		buf = pbAppendHandle(buf, 1, root.rawPtr())
	}
	resp, err := invokeMethod(0, 12, buf)
	if err != nil {
		return "", err
	}
	return readScalarAtField(resp, 1, (*pbReader).readString), nil
}

// Verifies that the provided AnalyzerOptions have a valid combination of
// settings.
func ValidateAnalyzerOptions(options *AnalyzerOptions) error {
	var buf []byte
	if options != nil {
		buf = pbAppendHandle(buf, 1, options.rawPtr())
	}
	_, err := invokeMethod(0, 13, buf)
	return err
}
